package com.wtm.ui;
import javax.swing.*; import java.awt.*; import java.awt.geom.*;
public final class IntelligenceTrendChart extends JComponent {
 private final java.util.List<Double> values; private final java.util.List<String> labels; private final double target;
 public IntelligenceTrendChart(java.util.List<Double> values,java.util.List<String> labels,double target){this.values=values;this.labels=labels;this.target=target;setPreferredSize(new Dimension(620,245));}
 @Override protected void paintComponent(Graphics g0){super.paintComponent(g0);if(values.size()<2)return;Graphics2D g=(Graphics2D)g0.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int l=58,r=18,t=24,b=38,w=getWidth()-l-r,h=getHeight()-t-b;double min=values.stream().mapToDouble(Double::doubleValue).min().orElse(0),max=values.stream().mapToDouble(Double::doubleValue).max().orElse(1);if(target>0){min=Math.min(min,target);max=Math.max(max,target);}double pad=Math.max(1,(max-min)*.12);min-=pad;max+=pad;g.setColor(new Color(Theme.border().getRed(),Theme.border().getGreen(),Theme.border().getBlue(),120));for(int i=0;i<4;i++){int y=t+i*h/3;g.drawLine(l,y,l+w,y);}if(target>0){int y=t+(int)((max-target)/(max-min)*h);g.setColor(Theme.warn());g.drawLine(l,y,l+w,y);g.drawString("Target "+fmt(target),l+6,Math.max(14,y-4));}Path2D path=new Path2D.Double();for(int i=0;i<values.size();i++){double v=values.get(i),x=l+(values.size()==1?0:(double)i*w/(values.size()-1)),y=t+(max-v)/(max-min)*h;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}g.setStroke(new BasicStroke(3f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));g.setColor(Theme.accent());g.draw(path);g.setStroke(new BasicStroke(1f));for(int i=0;i<values.size();i++){double v=values.get(i);int x=l+(values.size()==1?0:i*w/(values.size()-1)),y=t+(int)((max-v)/(max-min)*h);g.setColor(Theme.accent());g.fill(new Ellipse2D.Double(x-4,y-4,8,8));if(i==0||i==values.size()-1||values.size()<=8){g.setColor(Theme.muted());String lab=i<labels.size()?labels.get(i):Integer.toString(i+1);g.drawString(lab,x-12,t+h+20);}}g.setColor(Theme.muted());g.drawString(fmt(max),5,t+5);g.drawString(fmt(min),5,t+h);g.dispose();}
 private static String fmt(double v){return Math.abs(v)>=1000?String.format("%,.0f",v):String.format("%.1f",v);}
}
